/*
 * Typography role classes for @augurproject/design-system.
 *
 * Each class mirrors one `DESIGN.md` front-matter `typography` role,
 * keyed by the role name. Values are hand-authored to match `DESIGN.md`
 * exactly and verified against it by the fonts fixture driver
 * (`fixtures/verify-fonts.mjs`); the token pipeline (issue #3) generates
 * the primitive tokens, while role classes stay the maintained runtime
 * mapping. Do not add roles or values that are not in `DESIGN.md`.
 *
 * Families come from the `--augur-font-primary` and
 * `--augur-font-secondary` custom properties (`font-stacks.css` in the
 * package; the registry theme item declares them on `:root`). Font files
 * are delivered separately, by the package's optional `fonts.css` export
 * or by the consumer. Weights rely on Sora 400/600 and Schibsted
 * Grotesk 400 faces; the editorial roles (issue 45) deliberately reuse
 * the 400 faces, and no Sora Light dependency exists.
 *
 * Every rule sits in `@layer augur`.
 */

@layer augur {

/* Base: body copy uses the secondary voice unless a role overrides it. */
body {
  font-family: var(--augur-font-secondary);
  font-weight: 400;
}

/* DESIGN.md `typography.display` — Sora 600, 40/44, -0.01em. */
.augur-type-display {
  font-family: var(--augur-font-primary);
  font-weight: 600;
  font-size: 40px;
  line-height: 44px;
  letter-spacing: -0.01em;
}

/* DESIGN.md `typography.heading-1` — Sora 600, 28/34, -0.005em. */
.augur-type-heading-1 {
  font-family: var(--augur-font-primary);
  font-weight: 600;
  font-size: 28px;
  line-height: 34px;
  letter-spacing: -0.005em;
}

/* DESIGN.md `typography.heading-2` — Sora 600, 20/26. */
.augur-type-heading-2 {
  font-family: var(--augur-font-primary);
  font-weight: 600;
  font-size: 20px;
  line-height: 26px;
}

/* DESIGN.md `typography.body` — Schibsted Grotesk 400, 16/24. */
.augur-type-body {
  font-family: var(--augur-font-secondary);
  font-weight: 400;
  font-size: 16px;
  line-height: 24px;
}

/* DESIGN.md `typography.control` — Sora 600, 14/20. */
.augur-type-control {
  font-family: var(--augur-font-primary);
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
}

/* DESIGN.md `typography.ui` — Sora 400, 14/20. */
.augur-type-ui {
  font-family: var(--augur-font-primary);
  font-weight: 400;
  font-size: 14px;
  line-height: 20px;
}

/* DESIGN.md `typography.metadata` — Schibsted Grotesk 400, 12/16. */
.augur-type-metadata {
  font-family: var(--augur-font-secondary);
  font-weight: 400;
  font-size: 12px;
  line-height: 16px;
}

/* DESIGN.md `typography.editorial-title` — Sora 400, 40/48, -0.01em.
   The editorial voice: long-form titles set regular so size
   alone creates order. The 32/40 step below 600px is part of the
   adopted role, per the visual direction contract. */
.augur-type-editorial-title {
  font-family: var(--augur-font-primary);
  font-weight: 400;
  font-size: 40px;
  line-height: 48px;
  letter-spacing: -0.01em;
}

/* DESIGN.md `typography.editorial-section` — Sora 400, 28/34, -0.005em. */
.augur-type-editorial-section {
  font-family: var(--augur-font-primary);
  font-weight: 400;
  font-size: 28px;
  line-height: 34px;
  letter-spacing: -0.005em;
}

/* DESIGN.md `typography.editorial-label` — Schibsted Grotesk 400,
   12/16, +0.12em: short tracked uppercase labels. Wrapping is allowed;
   the tracking is never reduced to fit. */
.augur-type-editorial-label {
  font-family: var(--augur-font-secondary);
  font-weight: 400;
  font-size: 12px;
  line-height: 16px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* Adopted mobile steps for the editorial roles (visual direction
   contract). The seven inherited roles have no mobile steps. */
@media (max-width: 599px) {
  .augur-type-editorial-title {
    font-size: 32px;
    line-height: 40px;
  }

  .augur-type-editorial-section {
    font-size: 24px;
    line-height: 32px;
  }
}

} /* @layer augur */

/*
 * Structural base rules for @augurproject/design-system: the canvas
 * pairing on body, the keyboard focus ring, and the reduced-motion gate.
 *
 * Internal part of the public `theme.css` entry. The rules reference
 * semantic roles only (`./roles.css`), so they are identical in both
 * themes; the registry `augur-theme` item ships this file unchanged.
 * Every rule sits in `@layer augur`.
 */

@layer augur {

/* ------------------------------------------------------------------ */
/* Shared structural behavior — identical in both themes.              */
/* ------------------------------------------------------------------ */

/* Apply the canvas pairing so the default and selected themes render
   without consumer boilerplate (page-canvas-light / page-canvas-dark). */
body {
  background-color: var(--background);
  color: var(--foreground);
}

/* Focus: painted for keyboard focus only (focus-visible), as a 2px ring
   with a 2px offset in the theme's ring color. Structural rule shared by
   both themes; the color changes with the theme, nothing else does. The
   2px/2px geometry is structural and intentionally not emitted as a
   token. */
:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* Links take a 6px offset so the ring clears text and its underline
   (adopted from augur.net, issue #8). Same ring, larger offset. */
a:focus-visible {
  outline-offset: 6px;
}

/* Reduced motion: structural media-query gate over transition and
   animation properties (the reduced-motion collapse required by the
   theme contract). No duration tokens are adopted or emitted;
   the canonical collapse constant is inlined here and applies equally
   in both themes, including to consumer-authored motion. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

} /* @layer augur */
